<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DataTable from './DataTable.vue'
import { api } from './api'
const route=useRoute(),router=useRouter(),run=ref<Record<string,any>>(),error=ref(''),busy=ref(false),now=ref(Date.now())
const tabs=['hosts','ports','services','endpoints','credentials','screenshots','findings','events']
const tab=computed(()=>tabs.includes(String(route.query.tab))?String(route.query.tab):'hosts')
const fields:Record<string,string[]>={hosts:['ip','source','status','open_ports','services','first_seen_at','last_seen_at'],ports:['ip','port','transport','state','change'],services:['ip','port','transport','name','product','version','banner','confidence','details','change','first_seen_at','last_seen_at'],endpoints:['url','ip','port','source','status','details','screenshot'],credentials:['url','username','credential_id','status','evidence','attempted_at'],screenshots:['url','image','status','captured_at','error'],findings:['kind','severity','identity','evidence','created_at'],events:['created_at','stage','level','event_type','message','details']}
const filters:Record<string,string[]>={hosts:['new','unchanged','no-longer-observed'],ports:['open','no-longer-observed'],services:['open','new','changed','unchanged','no-longer-observed'],endpoints:['discovered','captured','error'],credentials:['not_attempted','not_supported','failed','successful','blocked','unknown'],screenshots:['pending','captured','error'],findings:['new_host','new_port','new_service','changed_service','credential_success','screenshot','scanner_error','no_longer_observed'],events:['info','warning','error']}
const columns=computed(()=>fields[tab.value].map(key=>({key,label:key.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())})))
let timer:ReturnType<typeof setInterval>
async function load(){try{run.value=await api(`/runs/${route.params.runId}`);now.value=Date.now()}catch(e){error.value=(e as Error).message}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),2500)})
onUnmounted(()=>clearInterval(timer))
const elapsed=computed(()=>{if(!run.value?.started_at)return 'Not started';const seconds=Math.max(0,Math.floor(((run.value.ended_at?Date.parse(run.value.ended_at):now.value)-Date.parse(run.value.started_at))/1000));return `${Math.floor(seconds/60)}m ${seconds%60}s`})
async function action(action:string){if(action==='stop'&&!confirm('Stop this run? Partial results will be preserved.'))return;busy.value=true;try{await api(`/runs/${route.params.runId}/${action}`,'POST');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function filterHost(ip:string){void router.replace({query:{tab:'services',services_search:ip}})}
</script>
<template><div class="page-heading"><div><p class="eyebrow">LIVE ASSESSMENT RESULTS</p><h1>Run overview<span class="accent">.</span></h1><RouterLink :to="`/scans/${route.params.id}`">← Definition & history</RouterLink></div><div class="actions" v-if="run"><button class="subtle" v-if="run.status==='running'" :disabled="busy" @click="action('pause')">Pause</button><button v-if="run.status==='paused'" :disabled="busy" @click="action('resume')">Resume</button><button class="danger subtle" v-if="['queued','running','pausing','paused'].includes(run.status)" :disabled="busy" @click="action('stop')">Stop</button></div></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="run"><section class="panel run-progress"><div class="actions"><span class="badge" :data-status="run.status">{{run.status}}</span><strong>{{run.current_stage}}</strong><span class="muted">{{elapsed}} · {{run.processed}} / {{run.total}} targets</span></div><progress :value="run.processed" :max="Math.max(1,run.total)" aria-label="Target progress"/><p class="error" v-if="run.error_summary">{{run.error_summary}}</p><p class="muted" v-if="run.status==='pausing'">Waiting for the active subprocess to finish before pausing.</p></section><div class="metrics"><div class="panel metric" v-for="key in ['hosts','open_ports','services','endpoints','credentials','screenshots','findings','errors']" :key="key"><span>{{key.replaceAll('_',' ')}}</span><strong>{{run.counts[key]||0}}</strong></div></div><nav class="tabs" aria-label="Result sections"><button v-for="name in tabs" :key="name" :aria-current="tab===name?'page':undefined" :class="{active:tab===name}" @click="router.replace({query:{...route.query,tab:name}})">{{name[0].toUpperCase()+name.slice(1)}}</button></nav><DataTable :key="tab+'-'+String(route.query.services_search||'')" :query-key="tab" :endpoint="`/runs/${run.id}/${tab}`" :columns="columns" :status-options="filters[tab]" :refresh="['queued','running','pausing','stopping'].includes(run.status)?3000:0" filter-status><template #ip="{value}"><button class="text-button" @click="filterHost(value)">{{value}}</button></template><template #credential_id="{value}">Credential {{String(value).slice(0,8)}}… · masked</template><template #image="{row}"><a v-if="row.content_url" :href="row.content_url" target="_blank" rel="noopener"><img class="thumbnail" :src="row.thumbnail_url" :alt="`Screenshot of ${row.url}`" loading="lazy"></a><span v-else>Unavailable</span></template><template #screenshot="{row}"><button class="text-button" @click="router.replace({query:{tab:'screenshots',screenshots_search:row.url}})">View captures</button></template></DataTable><details class="panel"><summary>Immutable approved configuration</summary><pre>{{JSON.stringify(run.config_snapshot,null,2)}}</pre></details></template></template>
